const i=JSON.parse('{"workId":"li-ji","chapter":{"id":"li-ji_ch-25","workId":"li-ji","order":25,"title":"祭統","difficulty":4,"estimatedMinutes":12,"passageIds":["li-ji_ch-25_p-1","li-ji_ch-25_p-2","li-ji_ch-25_p-3","li-ji_ch-25_p-4","li-ji_ch-25_p-5","li-ji_ch-25_p-6","li-ji_ch-25_p-7","li-ji_ch-25_p-8","li-ji_ch-25_p-9","li-ji_ch-25_p-10","li-ji_ch-25_p-11","li-ji_ch-25_p-12","li-ji_ch-25_p-13","li-ji_ch-25_p-14","li-ji_ch-25_p-15","li-ji_ch-25_p-16","li-ji_ch-25_p-17","li-ji_ch-25_p-18","li-ji_ch-25_p-19","li-ji_ch-25_p-20","li-ji_ch-25_p-21","li-ji_ch-25_p-22","li-ji_ch-25_p-23","li-ji_ch-25_p-24","li-ji_ch-25_p-25","li-ji_ch-25_p-26","li-ji_ch-25_p-27","li-ji_ch-25_p-28","li-ji_ch-25_p-29","li-ji_ch-25_p-30","li-ji_ch-25_p-31","li-ji_ch-25_p-32","li-ji_ch-25_p-33"],"tags":["儒家","禮樂"]},"passages":[{"id":"li-ji_ch-25_p-1","chapterId":"li-ji_ch-25","order":1,"canonicalText":"凡治人之道，莫急於禮。禮有五經，莫重於祭。夫祭者，非物自外至者也，自中出生於心也；心怵而奉之以禮。是故，唯賢者能盡祭之義。","sentenceIds":["li-ji_ch-25_p-1_s-1","li-ji_ch-25_p-1_s-2","li-ji_ch-25_p-1_s-3","li-ji_ch-25_p-1_s-4","li-ji_ch-25_p-1_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"凡治人的道，莫急於禮儀規程與道崇高德行與品性修養規範。禮儀規程與道崇高德行與品性修養規範有五經，莫重於祭。夫祭的人或禮儀規程與道崇高德行與品性修養規範制規範，絕不是物自外至的人或禮儀規程與道崇高德行與品性修養規範制規範啊，自中出生於心啊；心怵而且奉的以禮儀規程與道崇高德行與品性修養規範。正因為如此，唯賢的人或禮儀規程與道崇高德行與品性修養規範制規範能盡祭的正義公道之道義。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 1 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡治人之道，莫急於禮」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡治人之道，莫急於禮。禮有五經，莫重於祭。夫祭者，非……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-2","chapterId":"li-ji_ch-25","order":2,"canonicalText":"賢者之祭也，必受其福。非世所謂福也。福者，備也；備者，百順之名也。無所不順者，謂之備。言：內盡於己，而外順於道也。忠臣以事其君，孝子以事其親，其本一也。上則順於鬼神，外則順於君長，內則以孝於親。如此之謂備。唯賢者能備，能備然後能祭。是故，賢者之祭也：致其誠信與其忠敬，奉之以物，道之以禮，安之以樂，參之以時。明薦之而已矣。不求其為。此孝子之心也。","sentenceIds":["li-ji_ch-25_p-2_s-1","li-ji_ch-25_p-2_s-2","li-ji_ch-25_p-2_s-3","li-ji_ch-25_p-2_s-4","li-ji_ch-25_p-2_s-5","li-ji_ch-25_p-2_s-6","li-ji_ch-25_p-2_s-7","li-ji_ch-25_p-2_s-8","li-ji_ch-25_p-2_s-9","li-ji_ch-25_p-2_s-10","li-ji_ch-25_p-2_s-11","li-ji_ch-25_p-2_s-12","li-ji_ch-25_p-2_s-13","li-ji_ch-25_p-2_s-14"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"賢的人或禮儀規程與道崇高德行與品性修養規範制規範的祭啊，必受他的福。絕不是世所謂福啊。福的人或禮儀規程與道崇高德行與品性修養規範制規範，備啊；備的人或禮儀規程與道崇高德行與品性修養規範制規範，百順的名啊。無所不順的人或禮儀規程與道崇高德行與品性修養規範制規範，謂的備。言：內盡於己，而且外順於道啊。忠臣以事他的君，孝子以事他的親，他的本一啊。上則順於鬼神，外則順於君長，內則以孝於親。如此的謂備。唯賢的人或禮儀規程與道崇高德行與品性修養規範制規範能備，能備然後能祭。正因為如此，賢的人或禮儀規程與道崇高德行與品性修養規範制規範的祭啊：致他的誠信與他的忠敬，奉的以物，道的以禮儀規程與道崇高德行與品性修養規範，安的以雅樂和聲與心靈感化，參的以時。明薦的而且已矣。不求他的為。此孝子的心啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 2 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「賢者之祭也，必受其福」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「賢者之祭也，必受其福。非世所謂福也。福者，備也；備者……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-3","chapterId":"li-ji_ch-25","order":3,"canonicalText":"祭者，所以追養繼孝也。孝者畜也。順於道不逆於倫，是之謂畜。是故，孝子之事親也，有三道焉：生則養，沒則喪，喪畢則祭。養則觀其順也，喪則觀其哀也，祭則觀其敬而時也。盡此三道者，孝子之行也。","sentenceIds":["li-ji_ch-25_p-3_s-1","li-ji_ch-25_p-3_s-2","li-ji_ch-25_p-3_s-3","li-ji_ch-25_p-3_s-4","li-ji_ch-25_p-3_s-5","li-ji_ch-25_p-3_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"祭的人或禮儀規程與道崇高德行與品性修養規範制規範，所以追養繼孝啊。孝的人或禮儀規程與道崇高德行與品性修養規範制規範畜啊。順於道不逆於倫，是的謂畜。正因為如此，孝子的事親啊，有三道焉：生則養，沒則喪，喪畢則祭。養則觀他的順啊，喪則觀他的哀啊，祭則觀他的敬而且時啊。盡此三道的人或禮儀規程與道崇高德行與品性修養規範制規範，孝子的行啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 3 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「祭者，所以追養繼孝也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「祭者，所以追養繼孝也。孝者畜也。順於道不逆於倫，是之……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-4","chapterId":"li-ji_ch-25","order":4,"canonicalText":"既內自盡，又外求助，昏禮是也。故國君取夫人之辭曰：「請君之玉女與寡人共有敝邑，事宗廟社稷。」此求助之本也。夫祭也者，必夫婦親之，所以備外內之官也；官備則具備。水草之菹，陸產之醢，小物備矣；三牲之俎，八簋之實，美物備矣；昆蟲之異，草木之實，陰陽之物備矣。凡天之所生，地之所長，茍可薦者，莫不鹹在，示盡物也。外則盡物，內則盡志，此祭之心也。","sentenceIds":["li-ji_ch-25_p-4_s-1","li-ji_ch-25_p-4_s-2","li-ji_ch-25_p-4_s-3","li-ji_ch-25_p-4_s-4","li-ji_ch-25_p-4_s-5","li-ji_ch-25_p-4_s-6","li-ji_ch-25_p-4_s-7","li-ji_ch-25_p-4_s-8","li-ji_ch-25_p-4_s-9","li-ji_ch-25_p-4_s-10"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"既內自盡，又外求助，昏禮儀規程與道崇高德行與品性修養規範是啊。所以國君取夫人的辭說道：「請君的玉女與寡人共有敝邑，事宗廟社稷。」此求助的本啊。夫祭啊的人或禮儀規程與道崇高德行與品性修養規範制規範，必夫婦親的，所以備外內的官啊；官備則具備。水草的菹，陸產的醢，小物備矣；三牲的俎，八簋的實，美物備矣；昆蟲的異，草木的實，陰陽的物備矣。凡天的所生，地的所長，茍可薦的人或禮儀規程與道崇高德行與品性修養規範制規範，莫不鹹在，示盡物啊。外則盡物，內則盡志，此祭的心啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 4 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「既內自盡，又外求助，昏禮是也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「既內自盡，又外求助，昏禮是也。故國君取夫人之辭曰：「……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-5","chapterId":"li-ji_ch-25","order":5,"canonicalText":"是故，天子親耕於南郊，以共齊盛；王后蠶於北郊，以共純服。諸侯耕於東郊，亦以共齊盛；夫人蠶於北郊，以共冕服。天子諸侯非莫耕也，王后夫人非莫蠶也，身致其誠信，誠信之謂盡，盡之謂敬，敬盡然後可以事神明，此祭之道也。","sentenceIds":["li-ji_ch-25_p-5_s-1","li-ji_ch-25_p-5_s-2","li-ji_ch-25_p-5_s-3","li-ji_ch-25_p-5_s-4","li-ji_ch-25_p-5_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"正因為如此，天子親耕於南郊，以共齊盛；王后蠶於北郊，以共純服。諸侯耕於東郊，亦以共齊盛；夫人蠶於北郊，以共冕服。天子諸侯絕不是莫耕啊，王后夫人絕不是莫蠶啊，身致他的誠信，誠信的謂盡，盡的謂敬，敬盡然後可以事神明，此祭的道啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 5 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是故，天子親耕於南郊，以共齊盛」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是故，天子親耕於南郊，以共齊盛；王后蠶於北郊，以共純……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-6","chapterId":"li-ji_ch-25","order":6,"canonicalText":"及時將祭，君子乃齊。齊之為言齊也。齊不齊以致齊者也。是以君子非有大事也，非有恭敬也，則不齊。不齊則於物無防也，嗜慾無止也。及其將齊也，防其邪物，訖其嗜慾，耳不聽樂。故記曰：「齊者不樂」，言不敢散其志也。心不茍慮，必依於道；手足不茍動，必依於禮。是故君子之齊也，專致其精明之德也。","sentenceIds":["li-ji_ch-25_p-6_s-1","li-ji_ch-25_p-6_s-2","li-ji_ch-25_p-6_s-3","li-ji_ch-25_p-6_s-4","li-ji_ch-25_p-6_s-5","li-ji_ch-25_p-6_s-6","li-ji_ch-25_p-6_s-7","li-ji_ch-25_p-6_s-8","li-ji_ch-25_p-6_s-9","li-ji_ch-25_p-6_s-10"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"及時將祭，具有道德修養之君子賢士人階層乃齊。齊的為言齊啊。齊不齊以致齊的人或禮儀規程與道崇高德行與品性修養規範制規範啊。是以具有道德修養之君子賢士人階層絕不是有大事啊，絕不是有恭敬啊，則不齊。不齊則於物無防啊，嗜慾無止啊。及他的將齊啊，防他的邪物，訖他的嗜慾，耳不聽雅樂和聲與心靈感化。所以記說道：「齊的人或禮儀規程與道崇高德行與品性修養規範制規範不雅樂和聲與心靈感化」，言不敢散他的志啊。心不茍慮，必依於道；手足不茍動，必依於禮儀規程與道崇高德行與品性修養規範。正因為如此具有道德修養之君子賢士人階層的齊啊，專致他的精明的崇高德行與品性修養啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 6 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「及時將祭，君子乃齊」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「及時將祭，君子乃齊。齊之為言齊也。齊不齊以致齊者也。……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-7","chapterId":"li-ji_ch-25","order":7,"canonicalText":"故散齊七日以定之，致齊三日以齊之。定之之謂齊。齊者精明之至也，然後可以交於神明也。是故，先期旬有一日，宮宰宿夫人，夫人亦散齊七日，致齊三日。君致齊於外，夫人致齊於內，然後會於大廟。","sentenceIds":["li-ji_ch-25_p-7_s-1","li-ji_ch-25_p-7_s-2","li-ji_ch-25_p-7_s-3","li-ji_ch-25_p-7_s-4","li-ji_ch-25_p-7_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所以散齊七日以定的，致齊三日以齊的。定的的謂齊。齊的人或禮儀規程與道崇高德行與品性修養規範制規範精明的至啊，然後可以交於神明啊。正因為如此，先期旬有一日，宮宰宿夫人，夫人亦散齊七日，致齊三日。君致齊於外，夫人致齊於內，然後會於大廟。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 7 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「故散齊七日以定之，致齊三日以齊之」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「故散齊七日以定之，致齊三日以齊之。定之之謂齊。齊者精……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-8","chapterId":"li-ji_ch-25","order":8,"canonicalText":"君純冕立於阼，夫人副褘立於東房。君執圭瓚裸屍，大宗執璋瓚亞裸。及迎牲，君執紖，卿大夫從士執芻。宗婦執盎從夫人薦涗水。君執鸞刀羞嚌，夫人薦豆，此之謂夫婦親之。","sentenceIds":["li-ji_ch-25_p-8_s-1","li-ji_ch-25_p-8_s-2","li-ji_ch-25_p-8_s-3","li-ji_ch-25_p-8_s-4","li-ji_ch-25_p-8_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"君純冕立於阼，夫人副褘立於東房。君執圭瓚裸屍，大宗執璋瓚亞裸。及迎牲，君執紖，卿卿大夫貴族官員從士人階層執芻。宗婦執盎從夫人薦涗水。君執鸞刀羞嚌，夫人薦豆，此的謂夫婦親的。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 8 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「君純冕立於阼，夫人副褘立於東房」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「君純冕立於阼，夫人副褘立於東房。君執圭瓚裸屍，大宗執……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-9","chapterId":"li-ji_ch-25","order":9,"canonicalText":"及入舞，君執干戚就舞位，君為東上，冕而揔幹，率其群臣，以樂皇屍。是故天子之祭也，與天下樂之；諸侯之祭也，與竟內樂之。冕而揔幹，率其群臣，以樂皇屍，此與竟內樂之之義也。","sentenceIds":["li-ji_ch-25_p-9_s-1","li-ji_ch-25_p-9_s-2","li-ji_ch-25_p-9_s-3","li-ji_ch-25_p-9_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"及入舞，君執干戚就舞位，君為東上，冕而且揔幹，率他的群臣，以雅樂和聲與心靈感化皇屍。正因為如此天子的祭啊，與天下雅樂和聲與心靈感化的；諸侯的祭啊，與竟內雅樂和聲與心靈感化的。冕而且揔幹，率他的群臣，以雅樂和聲與心靈感化皇屍，此與竟內雅樂和聲與心靈感化的的正義公道之道義啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 9 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「及入舞，君執干戚就舞位，君為東上，冕而揔幹，率其群臣，以樂皇屍」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「及入舞，君執干戚就舞位，君為東上，冕而揔幹，率其群臣……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-10","chapterId":"li-ji_ch-25","order":10,"canonicalText":"夫祭有三重焉：獻之屬，莫重於裸，聲莫重於升歌，舞莫重於《武宿夜》，此周道也。凡三道者，所以假於外而以增君子之志也，故與志進退；志輕則亦輕，志重則亦重。輕其志而求外之重也，雖聖人弗能得也。是故君子之祭也，必身自盡也，所以明重也。道之以禮，以奉三重，而薦諸皇屍，此聖人之道也。","sentenceIds":["li-ji_ch-25_p-10_s-1","li-ji_ch-25_p-10_s-2","li-ji_ch-25_p-10_s-3","li-ji_ch-25_p-10_s-4","li-ji_ch-25_p-10_s-5","li-ji_ch-25_p-10_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"夫祭有三重焉：獻的屬，莫重於裸，聲莫重於升歌，舞莫重於《武宿夜》，此周道啊。凡三道的人或禮儀規程與道崇高德行與品性修養規範制規範，所以假於外而且以增具有道德修養之君子賢士人階層的志啊，所以與志進退；志輕則亦輕，志重則亦重。輕他的志而且求外的重啊，雖聖人弗能得啊。正因為如此具有道德修養之君子賢士人階層的祭啊，必身自盡啊，所以明重啊。道的以禮儀規程與道崇高德行與品性修養規範，以奉三重，而且薦諸皇屍，此聖人的道啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 10 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「夫祭有三重焉：獻之屬，莫重於裸，聲莫重於升歌，舞莫重於《武宿夜》，此周道也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「夫祭有三重焉：獻之屬，莫重於裸，聲莫重於升歌，舞莫重……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-11","chapterId":"li-ji_ch-25","order":11,"canonicalText":"夫祭有餕；餕者祭之末也，不可不知也。是故古之人有言曰：「善終者如始。」餕其是已。是故古之君子曰：「屍亦餕鬼神之餘也，惠術也，可以觀政矣。」是故屍謖，君與卿四人餕。君起，大夫六人餕；臣餕君之餘也。大夫起，士八人餕；賤餕貴之餘也。士起，各執其具以出，陳於堂下，百官進，徹之，下餕上之餘也。","sentenceIds":["li-ji_ch-25_p-11_s-1","li-ji_ch-25_p-11_s-2","li-ji_ch-25_p-11_s-3","li-ji_ch-25_p-11_s-4","li-ji_ch-25_p-11_s-5","li-ji_ch-25_p-11_s-6","li-ji_ch-25_p-11_s-7","li-ji_ch-25_p-11_s-8","li-ji_ch-25_p-11_s-9","li-ji_ch-25_p-11_s-10","li-ji_ch-25_p-11_s-11"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"夫祭有餕；餕的人或禮儀規程與道崇高德行與品性修養規範制規範祭的末啊，不可不知啊。正因為如此古的人有言說道：「善終的人或禮儀規程與道崇高德行與品性修養規範制規範如始。」餕他的是已。正因為如此古的君孔子先生親自開示教導說道：「屍亦餕鬼神的餘啊，惠術啊，可以觀政矣。」正因為如此屍謖，君與卿四人餕。君起，卿大夫貴族官員六人餕；臣餕君的餘啊。卿大夫貴族官員起，士人階層八人餕；賤餕貴的餘啊。士人階層起，各執他的具以出，陳於堂下，百官進，徹的，下餕上的餘啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 11 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「夫祭有餕」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「夫祭有餕；餕者祭之末也，不可不知也。是故古之人有言曰……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-12","chapterId":"li-ji_ch-25","order":12,"canonicalText":"凡餕之道，每變以眾，所以別貴賤之等，而興施惠之象也。是故以四簋黍見其修於廟中也。廟中者竟內之象也。祭者澤之大者也。是故上有大澤則惠必及下，顧上先下後耳。非上積重而下有凍餒之民也。是故上有大澤，則民夫人待於下流，知惠之必將至也，由餕見之矣。故曰：「可以觀政矣。」","sentenceIds":["li-ji_ch-25_p-12_s-1","li-ji_ch-25_p-12_s-2","li-ji_ch-25_p-12_s-3","li-ji_ch-25_p-12_s-4","li-ji_ch-25_p-12_s-5","li-ji_ch-25_p-12_s-6","li-ji_ch-25_p-12_s-7","li-ji_ch-25_p-12_s-8","li-ji_ch-25_p-12_s-9"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"凡餕的道，每變以眾，所以別貴賤的等，而且興施惠的象啊。正因為如此以四簋黍見他的修於廟中啊。廟中的人或禮儀規程與道崇高德行與品性修養規範制規範竟內的象啊。祭的人或禮儀規程與道崇高德行與品性修養規範制規範澤的大的人或禮儀規程與道崇高德行與品性修養規範制規範啊。正因為如此上有大澤則惠必及下，顧上先下後耳。絕不是上積重而且下有凍餒的民啊。正因為如此上有大澤，則民夫人待於下流，知惠的必將至啊，由餕見的矣。所以古代禮儀規程與道崇高德行與品性修養規範經名訓評論說道：「可以觀政矣。」。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 12 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡餕之道，每變以眾，所以別貴賤之等，而興施惠之象也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡餕之道，每變以眾，所以別貴賤之等，而興施惠之象也。……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-13","chapterId":"li-ji_ch-25","order":13,"canonicalText":"夫祭之為物大矣，其興物備矣。順以備者也，其教之本與？是故，君子之教也，外則教之以尊其君長，內則教之以孝於其親。是故，明君在上，則諸臣服從；崇事宗廟社稷，則子孫順孝。盡其道，端其義，而教生焉。","sentenceIds":["li-ji_ch-25_p-13_s-1","li-ji_ch-25_p-13_s-2","li-ji_ch-25_p-13_s-3","li-ji_ch-25_p-13_s-4","li-ji_ch-25_p-13_s-5","li-ji_ch-25_p-13_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"夫祭的為物大矣，他的興物備矣。順以備的人或禮儀規程與道崇高德行與品性修養規範制規範啊，他的教的本與？正因為如此，具有道德修養之君子賢士人階層的教啊，外則教的以尊他的君長，內則教的以孝於他的親。正因為如此，明君在上，則諸臣服從；崇事宗廟社稷，則子孫順孝。盡他的道，端他的正義公道之道義，而且教生焉。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 13 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「夫祭之為物大矣，其興物備矣」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「夫祭之為物大矣，其興物備矣。順以備者也，其教之本與？……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-14","chapterId":"li-ji_ch-25","order":14,"canonicalText":"是故君子之事君也，必身行之，所不安於上，則不以使下；所惡於下，則不以事上；非諸人，行諸己，非教之道也。是故君子之教也，必由其本，順之至也，祭其是與？故曰：祭者，教之本也已。","sentenceIds":["li-ji_ch-25_p-14_s-1","li-ji_ch-25_p-14_s-2","li-ji_ch-25_p-14_s-3","li-ji_ch-25_p-14_s-4","li-ji_ch-25_p-14_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"正因為如此具有道德修養之君子賢士人階層的事君啊，必身行的，所不安於上，則不以使下；所惡於下，則不以事上；絕不是諸人，行諸己，絕不是教的道啊。正因為如此具有道德修養之君子賢士人階層的教啊，必由他的本，順的至啊，祭他的是與？所以古代禮儀規程與道崇高德行與品性修養規範經名訓評論說道：祭的人或禮儀規程與道崇高德行與品性修養規範制規範，教的本啊已。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 14 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「是故君子之事君也，必身行之，所不安於上，則不以使下」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「是故君子之事君也，必身行之，所不安於上，則不以使下；……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-15","chapterId":"li-ji_ch-25","order":15,"canonicalText":"夫祭有十倫焉；見事鬼神之道焉，見君臣之義焉，見父子之倫焉，見貴賤之等焉，見親疏之殺焉，見爵賞之施焉，見夫婦之別焉，見政事之均焉，見長幼之序焉，見上下之際焉。此之謂十倫。","sentenceIds":["li-ji_ch-25_p-15_s-1","li-ji_ch-25_p-15_s-2","li-ji_ch-25_p-15_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"夫祭有十倫焉；見事鬼神的道焉，見君臣的正義公道之道義焉，見父子的倫焉，見貴賤的等焉，見親疏的殺焉，見爵賞的施焉，見夫婦的別焉，見政事的均焉，見長幼的序焉，見上下的際焉。此的謂十倫。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 15 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「夫祭有十倫焉」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「夫祭有十倫焉；見事鬼神之道焉，見君臣之義焉，見父子之……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-16","chapterId":"li-ji_ch-25","order":16,"canonicalText":"鋪筵設同幾，為依神也；詔祝於室，而出於祊，此交神明之道也。","sentenceIds":["li-ji_ch-25_p-16_s-1","li-ji_ch-25_p-16_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"鋪筵設同幾，為依神啊；詔祝於室，而且出於祊，此交神明的道啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 16 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「鋪筵設同幾，為依神也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「鋪筵設同幾，為依神也；詔祝於室，而出於祊，此交神明之……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-17","chapterId":"li-ji_ch-25","order":17,"canonicalText":"君迎牲而不迎屍，別嫌也。屍在廟門外，則疑於臣，在廟中則全於君；君在廟門外則疑於君，入廟門則全於臣、全於子。是故，不出者，明君臣之義也。","sentenceIds":["li-ji_ch-25_p-17_s-1","li-ji_ch-25_p-17_s-2","li-ji_ch-25_p-17_s-3","li-ji_ch-25_p-17_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"君迎牲而且不迎屍，別嫌啊。屍在廟門外，則疑於臣，在廟中則全於君；君在廟門外則疑於君，入廟門則全於臣、全於子。正因為如此，不出的人或禮儀規程與道崇高德行與品性修養規範制規範，明君臣的正義公道之道義啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 17 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「君迎牲而不迎屍，別嫌也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「君迎牲而不迎屍，別嫌也。屍在廟門外，則疑於臣，在廟中……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-18","chapterId":"li-ji_ch-25","order":18,"canonicalText":"夫祭之道，孫為王父屍。所使為屍者，於祭者子行也；父北面而事之，所以明子事父之道也。此父子之倫也。","sentenceIds":["li-ji_ch-25_p-18_s-1","li-ji_ch-25_p-18_s-2","li-ji_ch-25_p-18_s-3","li-ji_ch-25_p-18_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"夫祭的道，孫為王父屍。所使為屍的人或禮儀規程與道崇高德行與品性修養規範制規範，於祭的人或禮儀規程與道崇高德行與品性修養規範制規範子行啊；父北面而且事的，所以明子事父的道啊。此父子的倫啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 18 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「夫祭之道，孫為王父屍」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「夫祭之道，孫為王父屍。所使為屍者，於祭者子行也；父北……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-19","chapterId":"li-ji_ch-25","order":19,"canonicalText":"屍飲五，君洗玉爵獻卿；屍飲七，以瑤爵獻大夫；屍飲九，以散爵獻士及羣有司，皆以齒。明尊卑之等也。","sentenceIds":["li-ji_ch-25_p-19_s-1","li-ji_ch-25_p-19_s-2","li-ji_ch-25_p-19_s-3","li-ji_ch-25_p-19_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"屍飲五，君洗玉爵獻卿；屍飲七，以瑤爵獻卿大夫貴族官員；屍飲九，以散爵獻士人階層及羣有司，皆以齒。明尊卑的等啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 19 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「屍飲五，君洗玉爵獻卿」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「屍飲五，君洗玉爵獻卿；屍飲七，以瑤爵獻大夫；屍飲九，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-20","chapterId":"li-ji_ch-25","order":20,"canonicalText":"夫祭有昭穆，昭穆者，所以別父子、遠近、長幼、親疏之序而無亂也。是故，有事於大廟，則羣昭羣穆鹹在而不失其倫。此之謂親疏之殺也。","sentenceIds":["li-ji_ch-25_p-20_s-1","li-ji_ch-25_p-20_s-2","li-ji_ch-25_p-20_s-3"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"夫祭有昭穆，昭穆的人或禮儀規程與道崇高德行與品性修養規範制規範，所以別父子、遠近、長幼、親疏的序而且無亂啊。正因為如此，有事於大廟，則羣昭羣穆鹹在而且不失他的倫。此的謂親疏的殺啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 20 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「夫祭有昭穆，昭穆者，所以別父子、遠近、長幼、親疏之序而無亂也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「夫祭有昭穆，昭穆者，所以別父子、遠近、長幼、親疏之序……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-21","chapterId":"li-ji_ch-25","order":21,"canonicalText":"古者，明君爵有德而祿有功，必賜爵祿於大廟，示不敢專也。故祭之日，一獻，君降立於阼階之南，南鄉。所命北面，史由君右執策命之。再拜稽首。受書以歸，而舍奠於其廟。此爵賞之施也。","sentenceIds":["li-ji_ch-25_p-21_s-1","li-ji_ch-25_p-21_s-2","li-ji_ch-25_p-21_s-3","li-ji_ch-25_p-21_s-4","li-ji_ch-25_p-21_s-5","li-ji_ch-25_p-21_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"古的人或禮儀規程與道崇高德行與品性修養規範制規範，明君爵有崇高德行與品性修養而且祿有功，必賜爵祿於大廟，示不敢專啊。所以祭的日，一獻，君降立於阼階的南，南鄉。所命北面，史由君右執策命的。再拜稽首。受書以歸，而且舍奠於他的廟。此爵賞的施啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 21 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「古者，明君爵有德而祿有功，必賜爵祿於大廟，示不敢專也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「古者，明君爵有德而祿有功，必賜爵祿於大廟，示不敢專也……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-22","chapterId":"li-ji_ch-25","order":22,"canonicalText":"君卷冕立於阼，夫人副褘立於東房。夫人薦豆執校，執醴授之執鐙。屍酢夫人執柄，夫人受屍執足。夫婦相授受，不相襲處，酢必易爵。明夫婦之別也。","sentenceIds":["li-ji_ch-25_p-22_s-1","li-ji_ch-25_p-22_s-2","li-ji_ch-25_p-22_s-3","li-ji_ch-25_p-22_s-4","li-ji_ch-25_p-22_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在宗廟盛大祭祀典禮之中：國君身穿繪有龍紋的袞冕禮服肅立於東階阼階的尊位，國君夫人頭戴精美副飾首飾、身穿刺繡翟鳥圖紋的褘衣盛服肅立在東房門外。夫人進獻盛有祭肉的玉豆器皿之時，雙手端莊捧持著玉豆直立的木足（校）；手捧進獻甘美甜酒的醴爵遞交給國君之際，雙手穩穩承托在酒爵底座的支足（鐙）之處。受祭的尸神向君夫人回敬酢酒之時，尸神手握酒爵杯體中央的把手（柄），而夫人從尸神手中接納酒杯之時，雙手則謙卑承接在酒爵下方的底足；夫妻二人互相遞交呈遞祭祀酒器器皿之際，彼此雙手所觸握的部位各自不同絕不重疊交錯相碰，尸神與夫婦互相敬酒答謝之時每次皆更換嶄新潔淨的爵杯。先王制定這等微密謹嚴的儀軌，正是為了分明昭示男女夫婦內外有別、相敬如賓的崇高人倫節度。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 22 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「君卷冕立於阼，夫人副褘立於東房」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「君卷冕立於阼，夫人副褘立於東房。夫人薦豆執校，執醴授……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-23","chapterId":"li-ji_ch-25","order":23,"canonicalText":"凡為俎者，以骨為主。骨有貴賤；殷人貴髀，周人貴肩，凡前貴於後。俎者，所以明祭之必有惠也。是故，貴者取貴骨，賤者取賤骨。貴者不重，賤者不虛，示均也。惠均則政行，政行則事成，事成則功立。功之所以立者，不可不知也。俎者，所以明惠之必均也。善為政者如此，故曰：見政事之均焉。","sentenceIds":["li-ji_ch-25_p-23_s-1","li-ji_ch-25_p-23_s-2","li-ji_ch-25_p-23_s-3","li-ji_ch-25_p-23_s-4","li-ji_ch-25_p-23_s-5","li-ji_ch-25_p-23_s-6","li-ji_ch-25_p-23_s-7","li-ji_ch-25_p-23_s-8","li-ji_ch-25_p-23_s-9","li-ji_ch-25_p-23_s-10"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"凡為俎的人或禮儀規程與道崇高德行與品性修養規範制規範，以骨為主。骨有貴賤；殷人貴髀，周人貴肩，凡前貴於後。俎的人或禮儀規程與道崇高德行與品性修養規範制規範，所以明祭的必有惠啊。正因為如此，貴的人或禮儀規程與道崇高德行與品性修養規範制規範取貴骨，賤的人或禮儀規程與道崇高德行與品性修養規範制規範取賤骨。貴的人或禮儀規程與道崇高德行與品性修養規範制規範不重，賤的人或禮儀規程與道崇高德行與品性修養規範制規範不虛，示均啊。惠均則政行，政行則事成，事成則功立。功的所以立的人或禮儀規程與道崇高德行與品性修養規範制規範，不可不知啊。俎的人或禮儀規程與道崇高德行與品性修養規範制規範，所以明惠的必均啊。善為政的人或禮儀規程與道崇高德行與品性修養規範制規範如此，所以古代禮儀規程與道崇高德行與品性修養規範經名訓評論說道：見政事的均焉。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 23 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡為俎者，以骨為主」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡為俎者，以骨為主。骨有貴賤；殷人貴髀，周人貴肩，凡……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-24","chapterId":"li-ji_ch-25","order":24,"canonicalText":"凡賜爵，昭為一，穆為一。昭與昭齒，穆與穆齒，凡羣有司皆以齒，此之謂長幼有序。","sentenceIds":["li-ji_ch-25_p-24_s-1","li-ji_ch-25_p-24_s-2"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"凡是宗廟祭典禮成之後舉行向全體宗族賜酒酬飲之禮：屬於父子相承之「昭」位世代的同輩族人歸為一列，屬於「穆」位世代的同輩族人歸為一列。同在昭列的宗親內部完全依照年歲齒德長幼序坐受酒，同在穆列的宗親內部亦完全依照年歲長幼序坐受酒；朝廷前來助祭的各級文武執事有司官員，全數依照個人實際年歲齒德依次受賜爵杯；這就叫作宗法人倫之中長幼尊卑井然有序。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 24 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡賜爵，昭為一，穆為一」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡賜爵，昭為一，穆為一。昭與昭齒，穆與穆齒，凡羣有司……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-25","chapterId":"li-ji_ch-25","order":25,"canonicalText":"夫祭有畀輝胞翟閽者，惠下之道也。唯有德之君為能行此，明足以見之，仁足以與之。畀之為言與也，能以其餘畀其下者也。輝者，甲吏之賤者也；胞者，肉吏之賤者也；翟者，樂吏之賤者也；閽者，守門之賤者也。古者不使刑人守門，此四守者，吏之至賤者也。屍又至尊；以至尊既祭之末，而不忘至賤，而以其餘畀之。是故明君在上，則竟內之民無凍餒者矣，此之謂上下之際。","sentenceIds":["li-ji_ch-25_p-25_s-1","li-ji_ch-25_p-25_s-2","li-ji_ch-25_p-25_s-3","li-ji_ch-25_p-25_s-4","li-ji_ch-25_p-25_s-5","li-ji_ch-25_p-25_s-6","li-ji_ch-25_p-25_s-7","li-ji_ch-25_p-25_s-8","li-ji_ch-25_p-25_s-9","li-ji_ch-25_p-25_s-10","li-ji_ch-25_p-25_s-11"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"夫祭有畀輝胞翟閽的人或禮儀規程與道崇高德行與品性修養規範制規範，惠下的道啊。唯有崇高德行與品性修養的君為能行此，明足以見的，仁愛慈惠之聖德足以與的。畀的為言與啊，能以他的餘畀他的下的人或禮儀規程與道崇高德行與品性修養規範制規範啊。輝的人或禮儀規程與道崇高德行與品性修養規範制規範，甲吏的賤的人或禮儀規程與道崇高德行與品性修養規範制規範啊；胞的人或禮儀規程與道崇高德行與品性修養規範制規範，肉吏的賤的人或禮儀規程與道崇高德行與品性修養規範制規範啊；翟的人或禮儀規程與道崇高德行與品性修養規範制規範，雅樂和聲與心靈感化吏的賤的人或禮儀規程與道崇高德行與品性修養規範制規範啊；閽的人或禮儀規程與道崇高德行與品性修養規範制規範，守門的賤的人或禮儀規程與道崇高德行與品性修養規範制規範啊。古的人或禮儀規程與道崇高德行與品性修養規範制規範不使刑人守門，此四守的人或禮儀規程與道崇高德行與品性修養規範制規範，吏的至賤的人或禮儀規程與道崇高德行與品性修養規範制規範啊。屍又至尊；以至尊既祭的末，而且不忘至賤，而且以他的餘畀的。正因為如此明君在上，則竟內的民無凍餒的人或禮儀規程與道崇高德行與品性修養規範制規範矣，此的謂上下的際。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 25 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「夫祭有畀輝胞翟閽者，惠下之道也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「夫祭有畀輝胞翟閽者，惠下之道也。唯有德之君為能行此，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-26","chapterId":"li-ji_ch-25","order":26,"canonicalText":"凡祭有四時：春祭曰礿，夏祭曰禘，秋祭曰嘗，冬祭曰烝。礿、禘，陽義也；嘗、烝，陰義也。禘者陽之盛也，嘗者陰之盛也。故曰：莫重於禘、嘗。古者於禘也，發爵賜服，順陽義也；於嘗也，出田邑，發秋政，順陰義也。故記曰：「嘗之日，發公室，示賞也；草艾則墨；未發秋政，則民弗敢草也。」故曰：禘、嘗之義大矣。治國之本也，不可不知也。明其義者君也，能其事者臣也。不明其義，君人不全；不能其事，為臣不全。","sentenceIds":["li-ji_ch-25_p-26_s-1","li-ji_ch-25_p-26_s-2","li-ji_ch-25_p-26_s-3","li-ji_ch-25_p-26_s-4","li-ji_ch-25_p-26_s-5","li-ji_ch-25_p-26_s-6","li-ji_ch-25_p-26_s-7","li-ji_ch-25_p-26_s-8","li-ji_ch-25_p-26_s-9","li-ji_ch-25_p-26_s-10","li-ji_ch-25_p-26_s-11","li-ji_ch-25_p-26_s-12","li-ji_ch-25_p-26_s-13","li-ji_ch-25_p-26_s-14","li-ji_ch-25_p-26_s-15"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"凡祭有四時：春祭說道：礿，夏祭說道：禘，秋祭說道：嘗，冬祭說道：烝。礿、禘，陽正義公道之道義啊；嘗、烝，陰正義公道之道義啊。禘的人或禮儀規程與道崇高德行與品性修養規範制規範陽的盛啊，嘗的人或禮儀規程與道崇高德行與品性修養規範制規範陰的盛啊。所以古代禮儀規程與道崇高德行與品性修養規範經名訓評論說道：莫重於禘、嘗。古的人或禮儀規程與道崇高德行與品性修養規範制規範於禘啊，發爵賜服，順陽正義公道之道義啊；於嘗啊，出田邑，發秋政，順陰正義公道之道義啊。所以記說道：「嘗的日，發公室，示賞啊；草艾則墨；未發秋政，則民弗敢草啊。」所以古代禮儀規程與道崇高德行與品性修養規範經名訓評論說道：禘、嘗的正義公道之道義大矣。治國的本啊，不可不知啊。明他的正義公道之道義的人或禮儀規程與道崇高德行與品性修養規範制規範君啊，能他的事的人或禮儀規程與道崇高德行與品性修養規範制規範臣啊。不明他的正義公道之道義，君人不全；不能他的事，為臣不全。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 26 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「凡祭有四時：春祭曰礿，夏祭曰禘，秋祭曰嘗，冬祭曰烝」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「凡祭有四時：春祭曰礿，夏祭曰禘，秋祭曰嘗，冬祭曰烝。……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-27","chapterId":"li-ji_ch-25","order":27,"canonicalText":"夫義者，所以濟志也，諸德之發也。是故其德盛者，其志厚；其志厚者，其義章。其義章者，其祭也敬。祭敬則竟內之子孫莫敢不敬矣。是故君子之祭也，必身親蒞之；有故，則使人可也。雖使人也，君不失其義者，君明其義故也。其德薄者，其志輕，疑於其義，而求祭；使之必敬也，弗可得已。祭而不敬，何以為民父母矣？","sentenceIds":["li-ji_ch-25_p-27_s-1","li-ji_ch-25_p-27_s-2","li-ji_ch-25_p-27_s-3","li-ji_ch-25_p-27_s-4","li-ji_ch-25_p-27_s-5","li-ji_ch-25_p-27_s-6","li-ji_ch-25_p-27_s-7","li-ji_ch-25_p-27_s-8","li-ji_ch-25_p-27_s-9","li-ji_ch-25_p-27_s-10","li-ji_ch-25_p-27_s-11"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"夫正義公道之道義的人或禮儀規程與道崇高德行與品性修養規範制規範，所以濟志啊，諸崇高德行與品性修養的發啊。正因為如此他的崇高德行與品性修養盛的人或禮儀規程與道崇高德行與品性修養規範制規範，他的志厚；他的志厚的人或禮儀規程與道崇高德行與品性修養規範制規範，他的正義公道之道義章。他的正義公道之道義章的人或禮儀規程與道崇高德行與品性修養規範制規範，他的祭啊敬。祭敬則竟內的子孫莫敢不敬矣。正因為如此具有道德修養之君子賢士人階層的祭啊，必身親蒞的；有所以，則使人可啊。雖使人啊，君不失他的正義公道之道義的人或禮儀規程與道崇高德行與品性修養規範制規範，君明他的正義公道之道義所以啊。他的崇高德行與品性修養薄的人或禮儀規程與道崇高德行與品性修養規範制規範，他的志輕，疑於他的正義公道之道義，而且求祭；使的必敬啊，弗可得已。祭而且不敬，何以為民父母矣？","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 27 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「夫義者，所以濟志也，諸德之發也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「夫義者，所以濟志也，諸德之發也。是故其德盛者，其志厚……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-28","chapterId":"li-ji_ch-25","order":28,"canonicalText":"夫鼎有銘，銘者，自名也。自名以稱揚其先祖之美，而明著之後世者也。為先祖者，莫不有美焉，莫不有惡焉，銘之義，稱美而不稱惡，此孝子孝孫之心也。唯賢者能之。","sentenceIds":["li-ji_ch-25_p-28_s-1","li-ji_ch-25_p-28_s-2","li-ji_ch-25_p-28_s-3","li-ji_ch-25_p-28_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"夫鼎有銘，銘的人或禮儀規程與道崇高德行與品性修養規範制規範，自名啊。自名以稱揚他的先祖的美，而且明著的後世的人或禮儀規程與道崇高德行與品性修養規範制規範啊。為先祖的人或禮儀規程與道崇高德行與品性修養規範制規範，莫不有美焉，莫不有惡焉，銘的正義公道之道義，稱美而且不稱惡，此孝子孝孫的心啊。唯賢的人或禮儀規程與道崇高德行與品性修養規範制規範能的。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 28 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「夫鼎有銘，銘者，自名也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「夫鼎有銘，銘者，自名也。自名以稱揚其先祖之美，而明著……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-29","chapterId":"li-ji_ch-25","order":29,"canonicalText":"銘者，論譔其先祖之有德善，功烈勛勞慶賞聲名列於天下，而酌之祭器；自成其名焉，以祀其先祖者也。顯揚先祖，所以崇孝也。身比焉，順也。明示後世，教也。","sentenceIds":["li-ji_ch-25_p-29_s-1","li-ji_ch-25_p-29_s-2","li-ji_ch-25_p-29_s-3","li-ji_ch-25_p-29_s-4","li-ji_ch-25_p-29_s-5"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"銘的人或禮儀規程與道崇高德行與品性修養規範制規範，論譔他的先祖的有崇高德行與品性修養善，功烈勛勞慶賞聲名列於天下，而且酌的祭器；自成他的名焉，以祀他的先祖的人或禮儀規程與道崇高德行與品性修養規範制規範啊。顯揚先祖，所以崇孝啊。身比焉，順啊。明示後世，教啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 29 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「銘者，論譔其先祖之有德善，功烈勛勞慶賞聲名列於天下，而酌之祭器」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「銘者，論譔其先祖之有德善，功烈勛勞慶賞聲名列於天下，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-30","chapterId":"li-ji_ch-25","order":30,"canonicalText":"夫銘者，壹稱而上下皆得焉耳矣。是故君子之觀於銘也，既美其所稱，又美其所為。為之者，明足以見之，仁足以與之，知足以利之，可謂賢矣。賢而勿伐，可謂恭矣。","sentenceIds":["li-ji_ch-25_p-30_s-1","li-ji_ch-25_p-30_s-2","li-ji_ch-25_p-30_s-3","li-ji_ch-25_p-30_s-4"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"夫銘的人或禮儀規程與道崇高德行與品性修養規範制規範，壹稱而且上下皆得焉耳矣。正因為如此具有道德修養之君子賢士人階層的觀於銘啊，既美他的所稱，又美他的所為。為的的人或禮儀規程與道崇高德行與品性修養規範制規範，明足以見的，仁愛慈惠之聖德足以與的，知足以利的，可謂賢矣。賢而且勿伐，可謂恭矣。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 30 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「夫銘者，壹稱而上下皆得焉耳矣」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「夫銘者，壹稱而上下皆得焉耳矣。是故君子之觀於銘也，既……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-31","chapterId":"li-ji_ch-25","order":31,"canonicalText":"故衛孔悝之鼎銘曰：六月丁亥，公假於大廟。公曰：「叔舅！乃祖莊叔，左右成公。成公乃命莊叔隨難於漢陽，即宮於宗周，奔走無射。啟右獻公。獻公乃命成叔，纂乃祖服。乃考文叔，興舊耆欲，作率慶士，躬恤衛國，其勤公家，夙夜不解，民鹹曰：『休哉！』」公曰：「叔舅！予女銘：若纂乃考服。」悝拜稽首曰：「對揚以闢之，勤大命施於烝彝鼎。」此衛孔悝之鼎銘也。","sentenceIds":["li-ji_ch-25_p-31_s-1","li-ji_ch-25_p-31_s-2","li-ji_ch-25_p-31_s-3","li-ji_ch-25_p-31_s-4","li-ji_ch-25_p-31_s-5","li-ji_ch-25_p-31_s-6","li-ji_ch-25_p-31_s-7","li-ji_ch-25_p-31_s-8","li-ji_ch-25_p-31_s-9","li-ji_ch-25_p-31_s-10","li-ji_ch-25_p-31_s-11"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"所以衛孔悝的鼎銘說道：六月丁亥，公假於大廟。公說道：「叔舅！乃祖莊叔，左右成公。成公乃命莊叔隨難於漢陽，即宮於宗周，奔走無射。啟右獻公。獻公乃命成叔，纂乃祖服。乃考文叔，興舊耆欲，作率慶士人階層，躬恤衛國，他的勤公家，夙夜不解，民鹹說道：『休哉！』」公說道：「叔舅！予女銘：若纂乃考服。」悝拜稽首說道：「對揚以闢的，勤大命施於烝彝鼎。」此衛孔悝的鼎銘啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 31 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「故衛孔悝之鼎銘曰：六月丁亥，公假於大廟」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「故衛孔悝之鼎銘曰：六月丁亥，公假於大廟。公曰：「叔舅……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-32","chapterId":"li-ji_ch-25","order":32,"canonicalText":"古之君子論譔其先祖之美，而明著之後世者也。以比其身，以重其國家如此。子孫之守宗廟社稷者，其先祖無美而稱之，是誣也；有善而弗知，不明也；知而弗傳，不仁也。此三者，君子之所恥也。","sentenceIds":["li-ji_ch-25_p-32_s-1","li-ji_ch-25_p-32_s-2","li-ji_ch-25_p-32_s-3","li-ji_ch-25_p-32_s-4","li-ji_ch-25_p-32_s-5","li-ji_ch-25_p-32_s-6"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"古的具有道德修養之君子賢士人階層論譔他的先祖的美，而且明著的後世的人或禮儀規程與道崇高德行與品性修養規範制規範啊。以比他的身，以重他的國家如此。子孫的守宗廟社稷的人或禮儀規程與道崇高德行與品性修養規範制規範，他的先祖無美而且稱的，是誣啊；有善而且弗知，不明啊；知而且弗傳，不仁愛慈惠之聖德啊。此三的人或禮儀規程與道崇高德行與品性修養規範制規範，具有道德修養之君子賢士人階層的所恥啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 32 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「古之君子論譔其先祖之美，而明著之後世者也」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「古之君子論譔其先祖之美，而明著之後世者也。以比其身，……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}},{"id":"li-ji_ch-25_p-33","chapterId":"li-ji_ch-25","order":33,"canonicalText":"昔者，周公旦有勛勞於天下。周公既沒，成王、康王追念周公之所以勛勞者，而欲尊魯；故賜之以重祭。外祭，則郊社是也；內祭，則大嘗禘是也。夫大嘗禘，升歌《清廟》，下而管《象》；朱干玉戚，以舞《大武》；八佾，以舞《大夏》；此天子之樂也。康周公，故以賜魯也。子孫纂之，至於今不廢，所以明周公之德而又以重其國也。","sentenceIds":["li-ji_ch-25_p-33_s-1","li-ji_ch-25_p-33_s-2","li-ji_ch-25_p-33_s-3","li-ji_ch-25_p-33_s-4","li-ji_ch-25_p-33_s-5","li-ji_ch-25_p-33_s-6","li-ji_ch-25_p-33_s-7","li-ji_ch-25_p-33_s-8","li-ji_ch-25_p-33_s-9","li-ji_ch-25_p-33_s-10","li-ji_ch-25_p-33_s-11"],"sourceRefs":[{"label":"《禮記》—中國哲學書電子化計劃","edition":"阮元校刻《十三經註疏・禮記正義》","location":"https://ctext.org/liji/zh","accessedAt":"2026-08-31"},{"label":"《禮記》—維基文庫","edition":"鄭玄注・孔穎達疏《禮記正義》","location":"https://zh.wikisource.org/zh-hant/禮記","accessedAt":"2026-08-31"}],"readingAid":{"translation":"昔的人或禮儀規程與道崇高德行與品性修養規範制規範，周公旦有勛勞於天下。周公既沒，成王、康王追念周公的所以勛勞的人或禮儀規程與道崇高德行與品性修養規範制規範，而且欲尊魯；所以賜的以重祭。外祭，則郊社是啊；內祭，則大嘗禘是啊。夫大嘗禘，升歌《清廟》，下而且管《象》；朱干玉戚，以舞《大武》；八佾，以舞《大夏》；此天子的雅樂和聲與心靈感化啊。康周公，所以以賜魯啊。子孫纂的，至於今不廢，所以明周公的崇高德行與品性修養而且又以重他的國啊。","analysis":"【禮學篇旨與制度語境】\\\\n本段選自儒家禮學總典《禮記》〈祭統〉（第 33 節）。文本依據漢鄭玄注、唐孔穎達《禮記正義》與清孫希旦《禮記集解》之權威經學體系，詳載古代冠、婚、喪、祭、射、鄉、朝、聘等各項吉凶軍賓嘉禮儀制度。開篇「昔者，周公旦有勛勞於天下」奠定全篇之經學法度。\\\\n\\\\n【禮樂教化與章法義理】\\\\n1. 典章制度與名物考證：全段聚焦「昔者，周公旦有勛勞於天下。周公既沒，成王、康王追念周……」，深入剖析禮制名物、升降節奏、器用服色與宗法尊卑之嚴格規範，彰顯「禮者，天地之序也；樂者，天地之和也」之天人合一秩序。\\\\n2. 修身齊家與心性教化：禮非空洞形式，而在於「毋不敬」之誠敬心與「導民向善」之教化功用，將內在道德修養落實為外在彬彬有禮之君子行止。\\\\n\\\\n【經世憲章與文明價值】\\\\n《禮記》總結三代禮樂文明之精粹，其「大同世界」、「大學三綱領八條目」與「中庸之道」深刻奠定了中華文明兩千餘年之社會結構與精神家園，為儒家文化之最高禮制憲章。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"li-ji_ch-25_p-1_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-1","order":1,"canonicalText":"凡治人之道，莫急於禮。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-1_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-1","order":2,"canonicalText":"禮有五經，莫重於祭。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-1_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-1","order":3,"canonicalText":"夫祭者，非物自外至者也，自中出生於心也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-1_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-1","order":4,"canonicalText":"心怵而奉之以禮。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-1_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-1","order":5,"canonicalText":"是故，唯賢者能盡祭之義。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":1,"canonicalText":"賢者之祭也，必受其福。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":2,"canonicalText":"非世所謂福也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":3,"canonicalText":"福者，備也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":4,"canonicalText":"備者，百順之名也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":5,"canonicalText":"無所不順者，謂之備。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":6,"canonicalText":"言：內盡於己，而外順於道也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-7","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":7,"canonicalText":"忠臣以事其君，孝子以事其親，其本一也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-8","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":8,"canonicalText":"上則順於鬼神，外則順於君長，內則以孝於親。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-9","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":9,"canonicalText":"如此之謂備。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-10","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":10,"canonicalText":"唯賢者能備，能備然後能祭。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-11","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":11,"canonicalText":"是故，賢者之祭也：致其誠信與其忠敬，奉之以物，道之以禮，安之以樂，參之以時。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-12","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":12,"canonicalText":"明薦之而已矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-13","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":13,"canonicalText":"不求其為。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-2_s-14","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-2","order":14,"canonicalText":"此孝子之心也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-3_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-3","order":1,"canonicalText":"祭者，所以追養繼孝也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-3_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-3","order":2,"canonicalText":"孝者畜也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-3_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-3","order":3,"canonicalText":"順於道不逆於倫，是之謂畜。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-3_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-3","order":4,"canonicalText":"是故，孝子之事親也，有三道焉：生則養，沒則喪，喪畢則祭。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-3_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-3","order":5,"canonicalText":"養則觀其順也，喪則觀其哀也，祭則觀其敬而時也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-3_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-3","order":6,"canonicalText":"盡此三道者，孝子之行也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-4_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-4","order":1,"canonicalText":"既內自盡，又外求助，昏禮是也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-4_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-4","order":2,"canonicalText":"故國君取夫人之辭曰：「請君之玉女與寡人共有敝邑，事宗廟社稷。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-4_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-4","order":3,"canonicalText":"」此求助之本也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-4_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-4","order":4,"canonicalText":"夫祭也者，必夫婦親之，所以備外內之官也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-4_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-4","order":5,"canonicalText":"官備則具備。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-4_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-4","order":6,"canonicalText":"水草之菹，陸產之醢，小物備矣；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-4_s-7","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-4","order":7,"canonicalText":"三牲之俎，八簋之實，美物備矣；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-4_s-8","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-4","order":8,"canonicalText":"昆蟲之異，草木之實，陰陽之物備矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-4_s-9","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-4","order":9,"canonicalText":"凡天之所生，地之所長，茍可薦者，莫不鹹在，示盡物也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-4_s-10","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-4","order":10,"canonicalText":"外則盡物，內則盡志，此祭之心也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-5_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-5","order":1,"canonicalText":"是故，天子親耕於南郊，以共齊盛；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-5_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-5","order":2,"canonicalText":"王后蠶於北郊，以共純服。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-5_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-5","order":3,"canonicalText":"諸侯耕於東郊，亦以共齊盛；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-5_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-5","order":4,"canonicalText":"夫人蠶於北郊，以共冕服。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-5_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-5","order":5,"canonicalText":"天子諸侯非莫耕也，王后夫人非莫蠶也，身致其誠信，誠信之謂盡，盡之謂敬，敬盡然後可以事神明，此祭之道也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-6_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-6","order":1,"canonicalText":"及時將祭，君子乃齊。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-6_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-6","order":2,"canonicalText":"齊之為言齊也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-6_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-6","order":3,"canonicalText":"齊不齊以致齊者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-6_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-6","order":4,"canonicalText":"是以君子非有大事也，非有恭敬也，則不齊。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-6_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-6","order":5,"canonicalText":"不齊則於物無防也，嗜慾無止也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-6_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-6","order":6,"canonicalText":"及其將齊也，防其邪物，訖其嗜慾，耳不聽樂。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-6_s-7","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-6","order":7,"canonicalText":"故記曰：「齊者不樂」，言不敢散其志也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-6_s-8","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-6","order":8,"canonicalText":"心不茍慮，必依於道；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-6_s-9","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-6","order":9,"canonicalText":"手足不茍動，必依於禮。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-6_s-10","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-6","order":10,"canonicalText":"是故君子之齊也，專致其精明之德也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-7_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-7","order":1,"canonicalText":"故散齊七日以定之，致齊三日以齊之。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-7_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-7","order":2,"canonicalText":"定之之謂齊。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-7_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-7","order":3,"canonicalText":"齊者精明之至也，然後可以交於神明也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-7_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-7","order":4,"canonicalText":"是故，先期旬有一日，宮宰宿夫人，夫人亦散齊七日，致齊三日。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-7_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-7","order":5,"canonicalText":"君致齊於外，夫人致齊於內，然後會於大廟。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-8_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-8","order":1,"canonicalText":"君純冕立於阼，夫人副褘立於東房。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-8_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-8","order":2,"canonicalText":"君執圭瓚裸屍，大宗執璋瓚亞裸。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-8_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-8","order":3,"canonicalText":"及迎牲，君執紖，卿大夫從士執芻。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-8_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-8","order":4,"canonicalText":"宗婦執盎從夫人薦涗水。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-8_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-8","order":5,"canonicalText":"君執鸞刀羞嚌，夫人薦豆，此之謂夫婦親之。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-9_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-9","order":1,"canonicalText":"及入舞，君執干戚就舞位，君為東上，冕而揔幹，率其群臣，以樂皇屍。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-9_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-9","order":2,"canonicalText":"是故天子之祭也，與天下樂之；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-9_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-9","order":3,"canonicalText":"諸侯之祭也，與竟內樂之。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-9_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-9","order":4,"canonicalText":"冕而揔幹，率其群臣，以樂皇屍，此與竟內樂之之義也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-10_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-10","order":1,"canonicalText":"夫祭有三重焉：獻之屬，莫重於裸，聲莫重於升歌，舞莫重於《武宿夜》，此周道也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-10_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-10","order":2,"canonicalText":"凡三道者，所以假於外而以增君子之志也，故與志進退；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-10_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-10","order":3,"canonicalText":"志輕則亦輕，志重則亦重。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-10_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-10","order":4,"canonicalText":"輕其志而求外之重也，雖聖人弗能得也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-10_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-10","order":5,"canonicalText":"是故君子之祭也，必身自盡也，所以明重也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-10_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-10","order":6,"canonicalText":"道之以禮，以奉三重，而薦諸皇屍，此聖人之道也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-11_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-11","order":1,"canonicalText":"夫祭有餕；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-11_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-11","order":2,"canonicalText":"餕者祭之末也，不可不知也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-11_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-11","order":3,"canonicalText":"是故古之人有言曰：「善終者如始。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-11_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-11","order":4,"canonicalText":"」餕其是已。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-11_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-11","order":5,"canonicalText":"是故古之君子曰：「屍亦餕鬼神之餘也，惠術也，可以觀政矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-11_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-11","order":6,"canonicalText":"」是故屍謖，君與卿四人餕。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-11_s-7","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-11","order":7,"canonicalText":"君起，大夫六人餕；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-11_s-8","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-11","order":8,"canonicalText":"臣餕君之餘也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-11_s-9","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-11","order":9,"canonicalText":"大夫起，士八人餕；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-11_s-10","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-11","order":10,"canonicalText":"賤餕貴之餘也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-11_s-11","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-11","order":11,"canonicalText":"士起，各執其具以出，陳於堂下，百官進，徹之，下餕上之餘也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-12_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-12","order":1,"canonicalText":"凡餕之道，每變以眾，所以別貴賤之等，而興施惠之象也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-12_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-12","order":2,"canonicalText":"是故以四簋黍見其修於廟中也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-12_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-12","order":3,"canonicalText":"廟中者竟內之象也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-12_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-12","order":4,"canonicalText":"祭者澤之大者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-12_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-12","order":5,"canonicalText":"是故上有大澤則惠必及下，顧上先下後耳。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-12_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-12","order":6,"canonicalText":"非上積重而下有凍餒之民也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-12_s-7","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-12","order":7,"canonicalText":"是故上有大澤，則民夫人待於下流，知惠之必將至也，由餕見之矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-12_s-8","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-12","order":8,"canonicalText":"故曰：「可以觀政矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-12_s-9","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-12","order":9,"canonicalText":"」","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-13_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-13","order":1,"canonicalText":"夫祭之為物大矣，其興物備矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-13_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-13","order":2,"canonicalText":"順以備者也，其教之本與？","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-13_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-13","order":3,"canonicalText":"是故，君子之教也，外則教之以尊其君長，內則教之以孝於其親。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-13_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-13","order":4,"canonicalText":"是故，明君在上，則諸臣服從；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-13_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-13","order":5,"canonicalText":"崇事宗廟社稷，則子孫順孝。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-13_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-13","order":6,"canonicalText":"盡其道，端其義，而教生焉。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-14_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-14","order":1,"canonicalText":"是故君子之事君也，必身行之，所不安於上，則不以使下；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-14_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-14","order":2,"canonicalText":"所惡於下，則不以事上；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-14_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-14","order":3,"canonicalText":"非諸人，行諸己，非教之道也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-14_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-14","order":4,"canonicalText":"是故君子之教也，必由其本，順之至也，祭其是與？","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-14_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-14","order":5,"canonicalText":"故曰：祭者，教之本也已。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-15_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-15","order":1,"canonicalText":"夫祭有十倫焉；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-15_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-15","order":2,"canonicalText":"見事鬼神之道焉，見君臣之義焉，見父子之倫焉，見貴賤之等焉，見親疏之殺焉，見爵賞之施焉，見夫婦之別焉，見政事之均焉，見長幼之序焉，見上下之際焉。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-15_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-15","order":3,"canonicalText":"此之謂十倫。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-16_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-16","order":1,"canonicalText":"鋪筵設同幾，為依神也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-16_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-16","order":2,"canonicalText":"詔祝於室，而出於祊，此交神明之道也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-17_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-17","order":1,"canonicalText":"君迎牲而不迎屍，別嫌也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-17_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-17","order":2,"canonicalText":"屍在廟門外，則疑於臣，在廟中則全於君；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-17_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-17","order":3,"canonicalText":"君在廟門外則疑於君，入廟門則全於臣、全於子。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-17_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-17","order":4,"canonicalText":"是故，不出者，明君臣之義也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-18_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-18","order":1,"canonicalText":"夫祭之道，孫為王父屍。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-18_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-18","order":2,"canonicalText":"所使為屍者，於祭者子行也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-18_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-18","order":3,"canonicalText":"父北面而事之，所以明子事父之道也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-18_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-18","order":4,"canonicalText":"此父子之倫也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-19_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-19","order":1,"canonicalText":"屍飲五，君洗玉爵獻卿；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-19_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-19","order":2,"canonicalText":"屍飲七，以瑤爵獻大夫；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-19_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-19","order":3,"canonicalText":"屍飲九，以散爵獻士及羣有司，皆以齒。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-19_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-19","order":4,"canonicalText":"明尊卑之等也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-20_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-20","order":1,"canonicalText":"夫祭有昭穆，昭穆者，所以別父子、遠近、長幼、親疏之序而無亂也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-20_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-20","order":2,"canonicalText":"是故，有事於大廟，則羣昭羣穆鹹在而不失其倫。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-20_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-20","order":3,"canonicalText":"此之謂親疏之殺也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-21_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-21","order":1,"canonicalText":"古者，明君爵有德而祿有功，必賜爵祿於大廟，示不敢專也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-21_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-21","order":2,"canonicalText":"故祭之日，一獻，君降立於阼階之南，南鄉。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-21_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-21","order":3,"canonicalText":"所命北面，史由君右執策命之。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-21_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-21","order":4,"canonicalText":"再拜稽首。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-21_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-21","order":5,"canonicalText":"受書以歸，而舍奠於其廟。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-21_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-21","order":6,"canonicalText":"此爵賞之施也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-22_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-22","order":1,"canonicalText":"君卷冕立於阼，夫人副褘立於東房。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-22_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-22","order":2,"canonicalText":"夫人薦豆執校，執醴授之執鐙。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-22_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-22","order":3,"canonicalText":"屍酢夫人執柄，夫人受屍執足。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-22_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-22","order":4,"canonicalText":"夫婦相授受，不相襲處，酢必易爵。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-22_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-22","order":5,"canonicalText":"明夫婦之別也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-23_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-23","order":1,"canonicalText":"凡為俎者，以骨為主。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-23_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-23","order":2,"canonicalText":"骨有貴賤；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-23_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-23","order":3,"canonicalText":"殷人貴髀，周人貴肩，凡前貴於後。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-23_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-23","order":4,"canonicalText":"俎者，所以明祭之必有惠也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-23_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-23","order":5,"canonicalText":"是故，貴者取貴骨，賤者取賤骨。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-23_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-23","order":6,"canonicalText":"貴者不重，賤者不虛，示均也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-23_s-7","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-23","order":7,"canonicalText":"惠均則政行，政行則事成，事成則功立。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-23_s-8","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-23","order":8,"canonicalText":"功之所以立者，不可不知也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-23_s-9","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-23","order":9,"canonicalText":"俎者，所以明惠之必均也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-23_s-10","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-23","order":10,"canonicalText":"善為政者如此，故曰：見政事之均焉。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-24_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-24","order":1,"canonicalText":"凡賜爵，昭為一，穆為一。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-24_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-24","order":2,"canonicalText":"昭與昭齒，穆與穆齒，凡羣有司皆以齒，此之謂長幼有序。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-25_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-25","order":1,"canonicalText":"夫祭有畀輝胞翟閽者，惠下之道也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-25_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-25","order":2,"canonicalText":"唯有德之君為能行此，明足以見之，仁足以與之。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-25_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-25","order":3,"canonicalText":"畀之為言與也，能以其餘畀其下者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-25_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-25","order":4,"canonicalText":"輝者，甲吏之賤者也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-25_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-25","order":5,"canonicalText":"胞者，肉吏之賤者也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-25_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-25","order":6,"canonicalText":"翟者，樂吏之賤者也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-25_s-7","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-25","order":7,"canonicalText":"閽者，守門之賤者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-25_s-8","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-25","order":8,"canonicalText":"古者不使刑人守門，此四守者，吏之至賤者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-25_s-9","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-25","order":9,"canonicalText":"屍又至尊；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-25_s-10","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-25","order":10,"canonicalText":"以至尊既祭之末，而不忘至賤，而以其餘畀之。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-25_s-11","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-25","order":11,"canonicalText":"是故明君在上，則竟內之民無凍餒者矣，此之謂上下之際。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":1,"canonicalText":"凡祭有四時：春祭曰礿，夏祭曰禘，秋祭曰嘗，冬祭曰烝。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":2,"canonicalText":"礿、禘，陽義也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":3,"canonicalText":"嘗、烝，陰義也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":4,"canonicalText":"禘者陽之盛也，嘗者陰之盛也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":5,"canonicalText":"故曰：莫重於禘、嘗。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":6,"canonicalText":"古者於禘也，發爵賜服，順陽義也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-7","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":7,"canonicalText":"於嘗也，出田邑，發秋政，順陰義也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-8","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":8,"canonicalText":"故記曰：「嘗之日，發公室，示賞也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-9","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":9,"canonicalText":"草艾則墨；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-10","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":10,"canonicalText":"未發秋政，則民弗敢草也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-11","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":11,"canonicalText":"」故曰：禘、嘗之義大矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-12","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":12,"canonicalText":"治國之本也，不可不知也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-13","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":13,"canonicalText":"明其義者君也，能其事者臣也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-14","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":14,"canonicalText":"不明其義，君人不全；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-26_s-15","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-26","order":15,"canonicalText":"不能其事，為臣不全。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-27_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-27","order":1,"canonicalText":"夫義者，所以濟志也，諸德之發也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-27_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-27","order":2,"canonicalText":"是故其德盛者，其志厚；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-27_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-27","order":3,"canonicalText":"其志厚者，其義章。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-27_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-27","order":4,"canonicalText":"其義章者，其祭也敬。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-27_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-27","order":5,"canonicalText":"祭敬則竟內之子孫莫敢不敬矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-27_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-27","order":6,"canonicalText":"是故君子之祭也，必身親蒞之；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-27_s-7","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-27","order":7,"canonicalText":"有故，則使人可也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-27_s-8","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-27","order":8,"canonicalText":"雖使人也，君不失其義者，君明其義故也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-27_s-9","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-27","order":9,"canonicalText":"其德薄者，其志輕，疑於其義，而求祭；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-27_s-10","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-27","order":10,"canonicalText":"使之必敬也，弗可得已。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-27_s-11","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-27","order":11,"canonicalText":"祭而不敬，何以為民父母矣？","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-28_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-28","order":1,"canonicalText":"夫鼎有銘，銘者，自名也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-28_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-28","order":2,"canonicalText":"自名以稱揚其先祖之美，而明著之後世者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-28_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-28","order":3,"canonicalText":"為先祖者，莫不有美焉，莫不有惡焉，銘之義，稱美而不稱惡，此孝子孝孫之心也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-28_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-28","order":4,"canonicalText":"唯賢者能之。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-29_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-29","order":1,"canonicalText":"銘者，論譔其先祖之有德善，功烈勛勞慶賞聲名列於天下，而酌之祭器；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-29_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-29","order":2,"canonicalText":"自成其名焉，以祀其先祖者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-29_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-29","order":3,"canonicalText":"顯揚先祖，所以崇孝也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-29_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-29","order":4,"canonicalText":"身比焉，順也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-29_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-29","order":5,"canonicalText":"明示後世，教也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-30_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-30","order":1,"canonicalText":"夫銘者，壹稱而上下皆得焉耳矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-30_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-30","order":2,"canonicalText":"是故君子之觀於銘也，既美其所稱，又美其所為。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-30_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-30","order":3,"canonicalText":"為之者，明足以見之，仁足以與之，知足以利之，可謂賢矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-30_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-30","order":4,"canonicalText":"賢而勿伐，可謂恭矣。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-31_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-31","order":1,"canonicalText":"故衛孔悝之鼎銘曰：六月丁亥，公假於大廟。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-31_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-31","order":2,"canonicalText":"公曰：「叔舅！","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-31_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-31","order":3,"canonicalText":"乃祖莊叔，左右成公。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-31_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-31","order":4,"canonicalText":"成公乃命莊叔隨難於漢陽，即宮於宗周，奔走無射。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-31_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-31","order":5,"canonicalText":"啟右獻公。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-31_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-31","order":6,"canonicalText":"獻公乃命成叔，纂乃祖服。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-31_s-7","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-31","order":7,"canonicalText":"乃考文叔，興舊耆欲，作率慶士，躬恤衛國，其勤公家，夙夜不解，民鹹曰：『休哉！","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-31_s-8","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-31","order":8,"canonicalText":"』」公曰：「叔舅！","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-31_s-9","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-31","order":9,"canonicalText":"予女銘：若纂乃考服。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-31_s-10","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-31","order":10,"canonicalText":"」悝拜稽首曰：「對揚以闢之，勤大命施於烝彝鼎。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-31_s-11","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-31","order":11,"canonicalText":"」此衛孔悝之鼎銘也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-32_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-32","order":1,"canonicalText":"古之君子論譔其先祖之美，而明著之後世者也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-32_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-32","order":2,"canonicalText":"以比其身，以重其國家如此。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-32_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-32","order":3,"canonicalText":"子孫之守宗廟社稷者，其先祖無美而稱之，是誣也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-32_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-32","order":4,"canonicalText":"有善而弗知，不明也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-32_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-32","order":5,"canonicalText":"知而弗傳，不仁也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-32_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-32","order":6,"canonicalText":"此三者，君子之所恥也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-33_s-1","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-33","order":1,"canonicalText":"昔者，周公旦有勛勞於天下。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-33_s-2","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-33","order":2,"canonicalText":"周公既沒，成王、康王追念周公之所以勛勞者，而欲尊魯；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-33_s-3","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-33","order":3,"canonicalText":"故賜之以重祭。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-33_s-4","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-33","order":4,"canonicalText":"外祭，則郊社是也；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-33_s-5","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-33","order":5,"canonicalText":"內祭，則大嘗禘是也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-33_s-6","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-33","order":6,"canonicalText":"夫大嘗禘，升歌《清廟》，下而管《象》；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-33_s-7","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-33","order":7,"canonicalText":"朱干玉戚，以舞《大武》；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-33_s-8","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-33","order":8,"canonicalText":"八佾，以舞《大夏》；","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-33_s-9","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-33","order":9,"canonicalText":"此天子之樂也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-33_s-10","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-33","order":10,"canonicalText":"康周公，故以賜魯也。","chunks":[],"tags":[]},{"id":"li-ji_ch-25_p-33_s-11","workId":"li-ji","chapterId":"li-ji_ch-25","passageId":"li-ji_ch-25_p-33","order":11,"canonicalText":"子孫纂之，至於今不廢，所以明周公之德而又以重其國也。","chunks":[],"tags":[]}]}');export{i as default};
